import{_ as a,o,c as t,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Icon, color, and category","description":"Make Spaces distinguishable with an icon, color, and category.","frontmatter":{"title":"Icon, color, and category","description":"Make Spaces distinguishable with an icon, color, and category."},"headers":[],"relativePath":"en/spaces/symbol-und-farbe.md","filePath":"en/spaces/symbol-und-farbe.md","lastUpdated":1787319236000}'),s={name:"en/spaces/symbol-und-farbe.md"};function r(i,e,c,l,d,p){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="icon-color-and-category" tabindex="-1">Icon, color, and category <a class="header-anchor" href="#icon-color-and-category" aria-label="Permalink to &quot;Icon, color, and category&quot;">​</a></h1><p>With several Spaces, visual distinction helps more than any sorting. Icon and color show up in the overview and in the navigation.</p><h2 id="setting-an-icon" tabindex="-1">Setting an icon <a class="header-anchor" href="#setting-an-icon" aria-label="Permalink to &quot;Setting an icon&quot;">​</a></h2><p><strong>Set icon &amp; color</strong> opens the icon picker:</p><table tabindex="0"><thead><tr><th>Element</th><th>Function</th></tr></thead><tbody><tr><td><strong>Icon search</strong></td><td>Searches the available icons</td></tr><tr><td><strong>Transparent background</strong></td><td>Icon without a colored backdrop</td></tr><tr><td><strong>Upload icon file</strong></td><td>Your own image as the icon</td></tr><tr><td><strong>Reset</strong></td><td>Removes the icon again</td></tr></tbody></table><p>For custom icons, the prompt reads <em>Drop an image here… or click to browse</em>. If one is already set, the actions are called <strong>Change icon file</strong> and <strong>Remove icon file</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Icons by function, not by taste</p><p>This only becomes useful once the icons mean something: one icon for all client Spaces, another for internal ones, a third for the archive. Twenty pretty but arbitrary icons don&#39;t help you find anything.</p></div><div class="tip custom-block"><p class="custom-block-title">A custom icon for client projects</p><p>For Spaces a client sees via a <a href="/en/seiten/portal-veroeffentlichen">portal</a>, it&#39;s worth using the client&#39;s logo as the icon file — helpful for anyone working with several clients in parallel.</p></div><h2 id="setting-a-color" tabindex="-1">Setting a color <a class="header-anchor" href="#setting-a-color" aria-label="Permalink to &quot;Setting a color&quot;">​</a></h2><p>In the same dialog, you choose a color. The color picker remembers recently used colors under <strong>Saved colors</strong>; use <strong>Add</strong> to save the current color there.</p><p>With no saved colors, it reads: <em>No saved colors. Click &quot;Add&quot; to save the current color.</em></p><div class="warning custom-block"><p class="custom-block-title">Colors are plan-dependent</p><p>Space colors aren&#39;t available on every plan. Icons aren&#39;t affected by this.</p></div><div class="tip custom-block"><p class="custom-block-title">Color as a system</p><p>A color is most useful when it expresses a state — say, green for active projects, gray for completed ones. When the state changes, you change the color, and the overview stays meaningful.</p></div><h2 id="assigning-a-category" tabindex="-1">Assigning a category <a class="header-anchor" href="#assigning-a-category" aria-label="Permalink to &quot;Assigning a category&quot;">​</a></h2><p>A <strong>category</strong> bundles Spaces in the overview. Turn on <strong>Group by category</strong> to enable grouping; Spaces without one appear under <em>No category</em>.</p><p>Unlike icon and color, category affects structure, not just appearance.</p><div class="tip custom-block"><p class="custom-block-title">A few clear categories</p><p>Three to five is almost always enough: &quot;Clients,&quot; &quot;Internal,&quot; &quot;Archive.&quot; Too many categories are just as confusing as none at all.</p></div><h2 id="also-available-for-views-and-pages" tabindex="-1">Also available for Views and Pages <a class="header-anchor" href="#also-available-for-views-and-pages" aria-label="Permalink to &quot;Also available for Views and Pages&quot;">​</a></h2><p>Icon and color aren&#39;t only for Spaces:</p><ul><li><strong>Pages</strong> — via <em>Set icon &amp; color</em> in the page menu</li><li><strong>Views</strong> — the same function via the (⋮) menu of the respective View</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/spaces/space-anlegen">Create a Space</a></li><li><a href="/en/spaces/navigation">Set up navigation</a></li><li><a href="/en/seiten/seite-erstellen">Create and edit a page</a></li></ul>',22)])])}const u=a(s,[["render",r]]);export{g as __pageData,u as default};
